import{_ as a,o as l,c as e,ag as s}from"./chunks/framework.BZohXCq9.js";const k=JSON.parse('{"title":"RK3588 板端性能 A/B：怎样证明一条新流水线真的更省资源","description":"用 A1-B-A2、真实硬件计数器和功能门禁完成可重复的板端资源对比","frontmatter":{"title":"RK3588 板端性能 A/B：怎样证明一条新流水线真的更省资源","description":"用 A1-B-A2、真实硬件计数器和功能门禁完成可重复的板端资源对比","tags":["RK3588","Benchmark","GPU","Performance"],"date":"2026/07/18"},"headers":[],"relativePath":"linux/rk3588-performance-ab.md","filePath":"linux/rk3588-performance-ab.md","lastUpdated":1784519165000}'),t={name:"linux/rk3588-performance-ab.md"};function n(p,i,h,r,o,d){return l(),e("div",null,[...i[0]||(i[0]=[s(`<h1 id="rk3588-板端性能-a-b-怎样证明一条新流水线真的更省资源" tabindex="-1">RK3588 板端性能 A/B：怎样证明一条新流水线真的更省资源 <a class="header-anchor" href="#rk3588-板端性能-a-b-怎样证明一条新流水线真的更省资源" aria-label="Permalink to &quot;RK3588 板端性能 A/B：怎样证明一条新流水线真的更省资源&quot;">​</a></h1><p>把图像链路从 CPU copy 改成 DMA-BUF，把鱼眼矫正迁到 GPU，代码上看起来更高效，但性能结论不能来自架构图。板端 A/B 要回答三个问题：运行的是不是目标版本、业务功能是否等价、资源差异是否真的来自改动。</p><h2 id="为什么推荐-a1-→-b-→-a2" tabindex="-1">为什么推荐 A1 → B → A2 <a class="header-anchor" href="#为什么推荐-a1-→-b-→-a2" aria-label="Permalink to &quot;为什么推荐 A1 → B → A2&quot;">​</a></h2><p>直接先测旧版 B、再测新版 A，容易把温度、缓存、后台任务和测试顺序混进结果。更稳的顺序是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A1（新版） → B（基线） → A2（新版复测）</span></span></code></pre></div><p>如果 A1 与 A2 接近，而 B 稳定地落在另一水平，结果更可信。每轮都应包含固定预热和固定采样窗口，例如：</p><ul><li>预热 60 秒，让服务进入稳态；</li><li>采样 120 秒或更长；</li><li>三轮使用相同输入、频率和算法配置。</li></ul><h2 id="_1-先证明版本身份" tabindex="-1">1. 先证明版本身份 <a class="header-anchor" href="#_1-先证明版本身份" aria-label="Permalink to &quot;1. 先证明版本身份&quot;">​</a></h2><p>切换安装包或 release 后，旧进程可能仍持有相机设备。服务看似重启成功，实际采样的却是混合版本。</p><p>每轮开始前至少确认：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">servic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MainPID</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readlink</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/exe</span></span></code></pre></div><p>同时记录构建 commit、安装包 hash 与实际 executable 路径。任何一个参与主链的进程不是目标 release，本轮数据都应作废。</p><h2 id="_2-功能等价是性能测试的前置门禁" tabindex="-1">2. 功能等价是性能测试的前置门禁 <a class="header-anchor" href="#_2-功能等价是性能测试的前置门禁" aria-label="Permalink to &quot;2. 功能等价是性能测试的前置门禁&quot;">​</a></h2><p>CPU 降低可能只是某个模块没有工作。采样前要确认：</p><ul><li>相机 bundle 频率；</li><li>左右图或 atlas 频率；</li><li>IMU 输入频率；</li><li>VINS odometry 频率；</li><li>NPU 推理或编码输出是否持续；</li><li>health/watchdog 是否没有隐性重启。</li></ul><p>只有功能输出一致，资源对比才有意义。</p><h2 id="_3-cpu-不能只看目标进程" tabindex="-1">3. CPU 不能只看目标进程 <a class="header-anchor" href="#_3-cpu-不能只看目标进程" aria-label="Permalink to &quot;3. CPU 不能只看目标进程&quot;">​</a></h2><p>图像优化经常把成本从一个进程转移到内核线程、softirq、GPU、RGA 或另一个服务。建议同时记录：</p><ul><li>整机 CPU；</li><li>主链各进程 CPU/RSS；</li><li><code>NET_RX</code> 等 softirq；</li><li>RGA/NPU/GPU；</li><li>Shmem、page cache、slab 与普通可用内存。</li></ul><p>如果必须排除某个非业务服务，应在测试方案里提前声明；采样工具自身的 CPU 也要关闭或单列扣除。</p><h2 id="_4-gpu-必须使用-busy-idle-增量" tabindex="-1">4. GPU 必须使用 busy/idle 增量 <a class="header-anchor" href="#_4-gpu-必须使用-busy-idle-增量" aria-label="Permalink to &quot;4. GPU 必须使用 busy/idle 增量&quot;">​</a></h2><p>某些监控工具展示的是累计值或瞬时点，不能证明采样窗口里 GPU 真正工作。更可靠的做法是读取 Mali 的 <code>busy_time</code> 与 <code>idle_time</code>，用窗口首尾差值计算：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gpu_util = Δbusy / (Δbusy + Δidle)</span></span></code></pre></div><p>GPU 占用低也不等于 kernel 没执行。如果每帧 kernel 只有几毫秒、帧率又不高，平均利用率本来就可能很低。应结合 kernel duration、调用样本数和业务频率一起解释。</p><h2 id="_5-内存要拆成多层" tabindex="-1">5. 内存要拆成多层 <a class="header-anchor" href="#_5-内存要拆成多层" aria-label="Permalink to &quot;5. 内存要拆成多层&quot;">​</a></h2><p>至少分开观察：</p><ul><li>进程 RSS；</li><li>共享内存 Shmem；</li><li>DMA-BUF owner 与 size；</li><li>page cache；</li><li>slab；</li><li>NPU/ISP/编码器的内部池。</li></ul><p>只看 <code>free</code> 或 <code>MemAvailable</code>，很难判断优化到底减少了进程拷贝、共享内存，还是仅仅改变了缓存状态。</p><h2 id="_6-两分钟稳定不等于没有泄漏" tabindex="-1">6. 两分钟稳定不等于没有泄漏 <a class="header-anchor" href="#_6-两分钟稳定不等于没有泄漏" aria-label="Permalink to &quot;6. 两分钟稳定不等于没有泄漏&quot;">​</a></h2><p>短窗口可以用于比较稳态资源，但不能作为 leak gate。内存泄漏验证至少要补一小时以上的 steady-state，并记录：</p><ul><li>RSS slope；</li><li>Shmem slope；</li><li>DMA-BUF in-flight 数量；</li><li>slab/allocator 变化；</li><li>周期性重连或重启后的回落情况。</li></ul><h2 id="一份可复用的报告结构" tabindex="-1">一份可复用的报告结构 <a class="header-anchor" href="#一份可复用的报告结构" aria-label="Permalink to &quot;一份可复用的报告结构&quot;">​</a></h2><ol><li>测试目标与假设；</li><li>A/B 版本身份；</li><li>板卡、内核、配置与输入负载；</li><li>预热/采样窗口；</li><li>功能门禁结果；</li><li>CPU、内存、GPU、RGA、NPU、softirq；</li><li>A1/B/A2 原始值与聚合；</li><li>已证明的结论；</li><li>尚未证明的边界，如长期泄漏与 buffer 安全。</li></ol><p>好的性能报告不仅给出“快了多少”，还会清楚说明<strong>运行了什么、测了什么、没有证明什么</strong>。</p>`,34)])])}const u=a(t,[["render",n]]);export{k as __pageData,u as default};
